import{_ as a,C as o,o as p,c as n,j as t,a as i,E as s,a6 as m}from"./chunks/framework.CnPv4DE1.js";const _=JSON.parse('{"title":"为什么生产力建议正在毁掉你的生活","description":"","frontmatter":{"title":"为什么生产力建议正在毁掉你的生活","originalTitle":"Why Productivity Advice Is Ruining Your Life","date":"2022-02-11","originalUrl":"https://thedankoe.com/letters/why-productivity-advice-is-ruining-your-life/","minutes":10,"sourceHash":"822ffa98f65f574070a7572b6d28e4d290a102d7b35901585f675ca03ea1b288","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/why-productivity-advice-is-ruining-your-life/"}]]},"headers":[],"relativePath":"letters/why-productivity-advice-is-ruining-your-life.md","filePath":"letters/why-productivity-advice-is-ruining-your-life.md"}'),l={name:"letters/why-productivity-advice-is-ruining-your-life.md"};function c(h,e,u,d,g,f){const r=o("ArticleMeta");return p(),n("div",null,[e[0]||(e[0]=t("h1",{id:"为什么生产力建议正在毁掉你的生活",tabindex:"-1"},[i("为什么生产力建议正在毁掉你的生活 "),t("a",{class:"header-anchor",href:"#为什么生产力建议正在毁掉你的生活","aria-label":'Permalink to "为什么生产力建议正在毁掉你的生活"'},"​")],-1)),s(r),e[1]||(e[1]=m('<p><a href="https://www.youtube.com/embed/mZDAx8-iCY4?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><a href="https://open.spotify.com/embed/episode/6YLzyGzigQWsRcWOE0RPxT?si=pJEo-F_9TaiKTf7-M-EzyA&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><em><strong>你有没有注意到，有多少人过度劳累，却还以此为荣？</strong></em></p><p>这就是现代生产力的现状。奋斗逼文化大喊着“弱者才睡觉！”以及“工作到你无需再做自我介绍为止。”这种情怀听起来不错，但却抓错了重点。</p><p>在一个崇尚快速工作和立竿见影的世界里，保持绝对专注以及做有意义的长期工作的艺术已经被遗忘了。难怪成功者与失败者之间的差距越来越大。我们已经忘记了专注的复利效应。</p><p>通过这封信，我想为你提供2个我总结出的框架，它们将彻底改变你的生产力。</p><h1 id="生产力悖论" tabindex="-1">生产力悖论 <a class="header-anchor" href="#生产力悖论" aria-label="Permalink to &quot;生产力悖论&quot;">​</a></h1><p>创作者、企业家以及其他有影响力的人，将他们的成功归结于他们休息了多少，而不是工作了多少。</p><p>摘自 <a href="https://www.amazon.com/Rest-Alex-Soojung-Kim-Pang-audiobook/dp/B077DQR9KQ/ref=sr_1_1?crid=1SNXB8C612R2P&amp;keywords=rest%20alex%20soojung-kim%20pang&amp;qid=1640619004&amp;sprefix=rest%20ale%2Caps%2C135&amp;sr=8-1&amp;utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">亚历克斯·苏钟-金·庞（Alex Soojung-Kim Pang）的著作《休息》（Rest）</a>：</p><blockquote><p><em>“人们常说，聪明人可能工作得更巧妙，而不是更卖力，但真正有创造力的人压根就不工作。”</em></p></blockquote><p>庞还描述了古希腊人如何将休息视为一种恩赐，是文明生活的巅峰。罗马斯多葛学派认为，没有好的工作就不可能有好的生活。每一个古代社会都将工作和休息视为美好生活的必需品。一个提供了生存的手段，另一个则赋予了生活意义。</p><p>当提到“休息”或“放松”时，脑海中浮现的第一件事通常是现代对自我照顾的诠释。躺在沙发上吃着薯片，刷着你最爱的 Netflix 剧集。因为你的死党告诉你该“犒劳自己”，你就多吃了一大碗冰淇淋，并把自己淹没在葡萄酒中。任何其他被视为放松的行为，往往不过是伪装起来的懒惰。</p><p>当你去健身房时，你会每天竭尽全力举重12个小时吗？当然不会。你会安排高输出的时间，优先考虑恢复，并拥有一个结构化的训练计划。问题的根源在于人们的精神运作状态低下。缺乏创造力和好点子已经成为常态。你处于一种持续的大脑过度训练状态中，因为你试图变得和别人一样——你知道那会导致什么结果。</p><p>就像富有生产力的工作一样，你必须为刻意的休息安排时间。首先，我们需要把你目前对“自我照顾”的定义，换成开明版本的“主动恢复”。</p><p>让我向你介绍：<strong>填充 - 清空 - 使用（Fill – Empty – Use）</strong> 框架。</p><h2 id="填充-—-清空-—-使用" tabindex="-1">填充 — 清空 — 使用 <a class="header-anchor" href="#填充-—-清空-—-使用" aria-label="Permalink to &quot;填充 — 清空 — 使用&quot;">​</a></h2><p>几个月前<em>我有一条推文火了</em>：</p><blockquote><p>下午用书籍、学习和社交来填充你的大脑\\</p><p>睡前用写日记、做计划和冥想来清空你的大脑\\</p><p>早上用创作、输出和专注来使用你的大脑</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1456553636700504065?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2021年11月5日</a></p></blockquote><p>这是我使用 <strong>填充 — 清空 — 使用</strong> 框架的个人方式，所以让我们谈谈你如何在你的创作努力中运用它。</p><p>如何将其融入你的日常作息取决于你自己。尝试它的每个方面。如果你的精力在早晨最充沛，那就围绕早晨来安排你的工作和休息。夜猫子也一样。</p><p>这对那些致力于自己热爱事物的人最有效。一份副业、爱好项目，或是你选择去做的创作努力。而不是派给你的任务。你必须能够追寻自己的好奇心，从而激发热情和目标。这个框架将赋予你创作的火力，第二个框架将帮助你积累动能，转化为长期的自律。最终目标是 <a href="https://youtu.be/X56yHPhECWI?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">在追求毕生事业的同时获得丰厚的收入。</a></p><h3 id="填充" tabindex="-1">填充 <a class="header-anchor" href="#填充" aria-label="Permalink to &quot;填充&quot;">​</a></h3><p>不输入就无法输出。带着空空的大脑工作，就像开一辆油箱没油的车。<em>那是行不通的。</em> 你需要消化与你兴趣相关的书籍、文章、播客和其他信息。如果你热爱设计，就读一本与你当前技能水平相符的书。如果你想创业，就开始吸收商业内容。</p><p>我个人建议把阅读书籍或听有声书作为基础。<em>作者们花了10多年时间积累经验，将其浓缩成几百页，并以实惠的价格出售。</em> 你只需5到10小时就能吸收完毕。与其他内容相比，这种投资回报率是无与伦比的。播客是我的最爱之二。</p><h3 id="清空" tabindex="-1"><strong>清空</strong> <a class="header-anchor" href="#清空" aria-label="Permalink to &quot;**清空**&quot;">​</a></h3><p>李小龙（Bruce Lee）那句名言说明了一切：</p><blockquote><p><em>“清空你的心智，无形无相。像水一样。你把水倒进杯子，水就变成了杯子。你把水倒进瓶子，水就变成了瓶子。你把水倒进茶壶，水就变成了茶壶。水能流动，也能冲毁一切。像水一样吧，我的朋友。”</em></p></blockquote><p>这就是休息发挥作用的地方。我们没有沉溺于“自我照顾”，而是利用大部分空闲时间进行<em>主动恢复</em>。我喜欢把这些看作是冥想性的活动。有可能让你进入心流状态的活动。让你与所做之事融为一体的活动。让你与生活共同流动的活动。</p><p>去健身房、跑步、练武术、做瑜伽，或者去徒步。大自然沐浴——在自然中漫步，利用你的五种感官变得更加专注当下。正念活动，比如冥想、散步和呼吸法。</p><p>写日记是另一种流行的“清空大脑”的方法。每天晚上，写下你脑海里的一切。消极的想法、你今天过得怎样、你明天要做什么，以及其他零碎。这也是一个获得深度睡眠的诀窍。</p><p><strong>清空大脑的一个关键环节：</strong><em>在进行这些冥想性活动时，你需要一个地方来捕捉你的想法。</em> 如果你<em>填充</em>了你的大脑，你在这个时间段就会产生很棒的创意。别让这些创意随时间流逝。我捕捉创意的主要方法是在手机备忘录里建立一个持续更新的笔记。当到了<em>使用</em>我的大脑的时候，我就会参考它。</p><p>最后，你必须维持你的健康基础。大脑和身体是协同工作的。不健康的身体会导致毫无创造力的头脑。多喝水、保证睡眠，并吃营养密集的食物。</p><p>这些不仅是调节压力和情绪的绝佳方式，它们还有助于取得进展。当你不主动去思考时，你就给了潜意识喘息的空间。这种现象因为“洗澡时的灵光一闪”而广为人知，但它可以成为你精神武器库中的宝贵武器。<strong>当你不去刻意想出好点子时，你反而会有更好的点子。</strong></p><p>这些方法在训练自我意识方面不可思议地有效。这是生活中的一项关键技能。当我们讨论新颖性、效率和共时性时，这项技能就会派上用场。</p><p>传奇广告人奥格威（David Ogilvy）就用这种方法来构思他的大创意。他会为广告进行头脑风暴，然后放下工作，随着时间推移——完美的点子就会自己找上门来。奥格威不是唯一使用这种方法的人。昆汀·塔伦蒂诺（Quentin Tarantino）和其他传奇人物在他们的创作过程中都使用这种方法。</p><h3 id="使用" tabindex="-1"><strong>使用</strong> <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;**使用**&quot;">​</a></h3><p>这很简单。安排好时间，专心投入到与你目标相关的当前项目中。你什么时候做完全取决于你。一旦我们理解了为什么要这么做，我们就会讨论如何做到最好。</p><h2 id="新颖性-—-效率-—-共时性" tabindex="-1"><strong>新颖性 — 效率 — 共时性</strong> <a class="header-anchor" href="#新颖性-—-效率-—-共时性" aria-label="Permalink to &quot;**新颖性 — 效率 — 共时性**&quot;">​</a></h2><p><strong>填充 — 清空 — 使用</strong> 框架之所以如此有效，是因为<em>灵感行动法则</em>。</p><p>简而言之，当你被日常的刺激和经历所启发时——你会感到有创作的冲动。你会感受到某种渴望被掌握的事物的牵引。它不是一项苦差事，<em>如果</em>你真的受到启发，它自然而然就会发生。为了获得启发，你需要追求<em>你</em>的兴趣。而不是别人的。</p><p>你绝不能压抑你好奇的天性。<em>这就是为什么人们在小学时讨厌阅读，并且后来继续讨厌他们没有出路的死板工作。</em> 零灵感，毫无个人兴趣。在追求的事物上缺乏选择权。拒绝去探索潜藏在未知中的无限潜能的召唤。</p><h3 id="新颖性" tabindex="-1">新颖性 <a class="header-anchor" href="#新颖性" aria-label="Permalink to &quot;新颖性&quot;">​</a></h3><p>人类的大脑热爱新事物。新颖的体验。多巴胺是这里的驱动力，<em>它将信号与噪音分开</em>。将行动与分心分开。当行动不符合 <a href="https://twitter.com/thedankoe/status/1464263989270089730?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">你想成为的那个人</a> 时，它就被滥用了。那就是……当你没有一个<em>你</em>自己定义的愿景、目标或优先事项时。</p><p>当你消费了错误的东西时，多巴胺会迅速将你卷入负面螺旋。例子包括社交媒体上的自嘲梗图、无脑娱乐、色情内容，以及其他来自近期技术进步的思想劫持物。</p><blockquote><p>人类渴望新颖性\\</p><p>媒体公司知道这一点。\\</p><p>所以他们给了你想要的。让你成为廉价多巴胺的奴隶。\\</p><p>如果你读书、走向户外、突破自我，并在屏幕之外寻找新奇。\\</p><p>你将会沉迷于进步，而不是自我毁灭。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1475475826602872848?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2021年12月27日</a></p></blockquote><h2 id="效率" tabindex="-1"><strong>效率</strong> <a class="header-anchor" href="#效率" aria-label="Permalink to &quot;**效率**&quot;">​</a></h2><p>我们明白你必须<em>使用</em>你的大脑，但我们需要结构。我们需要效率，这样你就不会花12个小时去完成3个小时的工作。<strong>效率就是把事情变得简单到令人发指的地步，以至于如果你不这么做，就会显得自己很愚蠢。</strong></p><p><em>这里有6个让你进入深度心流状态的速射技巧。</em> 只有当你的行动与你的目标和兴趣一致时，这才会奏效，这意味着你的行动背后有明确的意图。你正在朝着某个目标延伸。<em>新颖性和共时性必须存在。</em></p><p><strong>技巧 1）留出并安排好时间来使用大脑，进行深度工作。</strong> 把它放进你的日程表。把它写在你的墙上。用干擦笔把它写在浴室的墙上。务必让你清楚地<em>知道</em>，你将在那个特定时间段工作。</p><p><strong>技巧 2）在前一天晚上计划好你的一天</strong> <a href="https://shop.thedankoe.com/planner?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer"><strong>（如果没有的话，使用我的免费计划表）</strong></a><strong>。</strong> 提醒自己你的愿景、目标和优先事项。给自己安排2-3个能带来杠杆效应的任务。有些人能处理更多。从2-3个开始，然后根据情况增加。带来杠杆效应的任务是那些能最快推动你朝着目标迈进的任务。</p><p><strong>技巧 3）将自己置于有助于深度工作的环境中。</strong> 我最喜欢的地方是咖啡馆、酒店大堂、飞机上，或者是任何与你睡觉的地方分开的地方。</p><p><strong>技巧 4）设定一个 45 分钟到 2 小时的定时器。</strong> 再次强调，你必须自己去试验。这是一心一意的专注时间。没有任何干扰。去写作、设计、建立联系、编辑、发布、构建。如果有必要，使用 Freedom 应用程序来屏蔽干扰你的应用。</p><p><strong>技巧 5）听没有歌词的音乐——或者能让你心情好的音乐。</strong> 我最喜欢的一些是回响贝斯（dubstep）、电子舞曲（EDM）和汉斯·季默（Hans Zimmer）的配乐。</p><p><strong>技巧 6）定时器一响，离开椅子去散步 10 分钟。</strong> 在散步期间，提醒自己你的下一个任务是什么，你正在努力实现什么目标，以及你为什么要努力——最终目标是什么？有时我会听有声书来激发更多的新奇感和同步性，为我的下一次工作环节注入能量。</p><p>这些都是灵活可变的。我的公式并不完美。生活就是一系列的科学实验。去找到对你有效的那个。</p><h2 id="同步性-synchronicity" tabindex="-1"><strong>同步性（Synchronicity）</strong> <a class="header-anchor" href="#同步性-synchronicity" aria-label="Permalink to &quot;**同步性（Synchronicity）**&quot;">​</a></h2><p>同步性是让你全速前进并维持长期进步的关键。在心理学中，有一种被称为“模式识别”（pattern recognition）的现象，它描述了<em>“一种将刺激信息与记忆信息相匹配的认知过程。”</em></p><p>意思是：这是一种更强有力的新奇感。你正在将点滴联系起来，而且能真切地<em>感受</em>到进步。从而产生更多有益的多巴胺。</p><p>当你用我们之前讨论过的<strong>填充——清空——使用</strong>框架来<em>清空</em>大脑时，你在身体和心理上创建了锚点。当你<em>填充</em>大脑时，你就创建了一个点，这个点可以与另一个点连接起来。</p><p>按照<em>我</em>的定义，同步性是随着时间的推移将点滴联系起来的过程。而谷歌快速搜索给出的定义是：</p><blockquote><p><em>“……精神上的同步性是被战略性地精心策划和完美对齐的，旨在传递信息、提供指导，或让我们确信自己正走在正确的道路上。”</em></p></blockquote><p>看似无关的概念变得更容易理解，因为它们与之前的其他想法联系在了一起。这把你拉回一种冥想般的心流状态中。你会获得由动能带来的持续能量供应——这可以说是世界上最美妙的感觉。爱上这个过程。为你之痴狂。</p><p>随着你在毕生事业中取得更多进展，同步性出现的频率会越来越高。你能够在一天中维持不同程度的心流状态。</p><p><em>我认为同步性——即各种想法的交汇融合——正是成功人士的秘诀所在。</em> 它是人们所看到的融合伟大理念的天才之举。它是点燃他们改变世界这一内在火焰的燃料。<em>它是持续且复利的心智、身体和精神收益在他们业务上的显化。</em></p><p>这是一种只能通过亲身体验才能领悟的感觉。</p><p><strong>这一切听起来都很棒，但如果不去行动，那就毫无意义。</strong></p><p>这些框架和流程能让行动变得更容易，但决定权完全在你手中。你可能有一些根深蒂固的坏习惯，你需要去察觉它们。有意识地规划出你想成为什么样的人，并坚持不懈地采取行动。</p><p>这是唯一值得的生活方式。你要么有意识地活着，要么无意识地走向死亡。先从每天花 5 分钟填充大脑、5 分钟清空大脑和 5 分钟使用大脑开始。这就是最终启动动能雪球所需的一切。时间不是借口。尽你所能去做。</p><p>如果你喜欢这期《The Mastery Letter》，请在 Twitter 上告诉我。写条推文分享你的想法并 @ 我（@thedankoe）。我一直在尽力为你带来最高质量的内容，并将继续如此。</p><p>周末愉快，</p><p>– Dan Koe</p><hr><p><a href="/en/letters/why-productivity-advice-is-ruining-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',73))])}const k=a(l,[["render",c]]);export{_ as __pageData,k as default};
